1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { createGoalSchema, updateGoalSchema } from "@paperclipai/shared";
4	import { trackGoalCreated } from "@paperclipai/shared/telemetry";
5	import { validate } from "../middleware/validate.js";
6	import { goalService, logActivity } from "../services/index.js";
7	import { assertCompanyAccess, getActorInfo } from "./authz.js";
8	import { getTelemetryClient } from "../telemetry.js";
9	
10	export function goalRoutes(db: Db) {
11	  const router = Router();
12	  const svc = goalService(db);
13	
14	  router.get("/companies/:companyId/goals", async (req, res) => {
15	    const companyId = req.params.companyId as string;
16	    assertCompanyAccess(req, companyId);
17	    const result = await svc.list(companyId);
18	    res.json(result);
19	  });
20	
21	  router.get("/goals/:id", async (req, res) => {
22	    const id = req.params.id as string;
23	    const goal = await svc.getById(id);
24	    if (!goal) {
25	      res.status(404).json({ error: "Goal not found" });
26	      return;
27	    }
28	    assertCompanyAccess(req, goal.companyId);
29	    res.json(goal);
30	  });
31	
32	  router.post("/companies/:companyId/goals", validate(createGoalSchema), async (req, res) => {
33	    const companyId = req.params.companyId as string;
34	    assertCompanyAccess(req, companyId);
35	    const goal = await svc.create(companyId, req.body);
36	    const actor = getActorInfo(req);
37	    await logActivity(db, {
38	      companyId,
39	      actorType: actor.actorType,
40	      actorId: actor.actorId,
41	      agentId: actor.agentId,
42	      action: "goal.created",
43	      entityType: "goal",
44	      entityId: goal.id,
45	      details: { title: goal.title },
46	    });
47	    const telemetryClient = getTelemetryClient();
48	    if (telemetryClient) {
49	      trackGoalCreated(telemetryClient, { goalLevel: goal.level });
50	    }
51	    res.status(201).json(goal);
52	  });
53	
54	  router.patch("/goals/:id", validate(updateGoalSchema), async (req, res) => {
55	    const id = req.params.id as string;
56	    const existing = await svc.getById(id);
57	    if (!existing) {
58	      res.status(404).json({ error: "Goal not found" });
59	      return;
60	    }
61	    assertCompanyAccess(req, existing.companyId);
62	    const goal = await svc.update(id, req.body);
63	    if (!goal) {
64	      res.status(404).json({ error: "Goal not found" });
65	      return;
66	    }
67	
68	    const actor = getActorInfo(req);
69	    await logActivity(db, {
70	      companyId: goal.companyId,
71	      actorType: actor.actorType,
72	      actorId: actor.actorId,
73	      agentId: actor.agentId,
74	      action: "goal.updated",
75	      entityType: "goal",
76	      entityId: goal.id,
77	      details: req.body,
78	    });
79	
80	    res.json(goal);
81	  });
82	
83	  router.delete("/goals/:id", async (req, res) => {
84	    const id = req.params.id as string;
85	    const existing = await svc.getById(id);
86	    if (!existing) {
87	      res.status(404).json({ error: "Goal not found" });
88	      return;
89	    }
90	    assertCompanyAccess(req, existing.companyId);
91	    const goal = await svc.remove(id);
92	    if (!goal) {
93	      res.status(404).json({ error: "Goal not found" });
94	      return;
95	    }
96	
97	    const actor = getActorInfo(req);
98	    await logActivity(db, {
99	      companyId: goal.companyId,
100	      actorType: actor.actorType,
101	      actorId: actor.actorId,
102	      agentId: actor.agentId,
103	      action: "goal.deleted",
104	      entityType: "goal",
105	      entityId: goal.id,
106	    });
107	
108	    res.json(goal);
109	  });
110	
111	  return router;
112	}
